async function loadProfile(id) {
  try {
    const [user, orders] = await Promise.all([getJSON(`/u/${id}`), getJSON(`/u/${id}/orders`)]);
    return { user, orders };
  } catch (error) {
    if (error.cause?.status === 404) return null;
    throw error;
  } finally {
    hideSpinner();
  }
}

async function getJSON(url, options) {
  const response = await fetch(url, options);
  if (!response.ok) throw new Error(`Request failed: ${response.status}`, { cause: response });
  return response.json();
}

